<?php require 'db.php';require 'helpers.php';$errors=[];$ok='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$name=trim(strip_tags($_POST['name']??''));$email=trim($_POST['email']??'');$message=trim(strip_tags($_POST['message']??''));if(mb_strlen($name)<2)$errors[]='Name must be at least 2 characters.';if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Valid email required.';if(mb_strlen($message)<5)$errors[]='Message must be at least 5 characters.';if(!$errors){$fp=fopen(__DIR__.'/submissions.csv','ab');if($fp&&flock($fp,LOCK_EX)){fputcsv($fp,[$name,$email,$message,date('c')]);flock($fp,LOCK_UN);fclose($fp);$ok='Form submitted and stored in CSV.';}else{$errors[]='Storage unavailable.';}}}page_header('Practical 7 - Form Storage');if($ok)echo '<div class="notice">'.e($ok).'</div>';if($errors)echo '<div class="error">'.e(implode(' ',$errors)).'</div>';?><section class="panel"><h2>Contact Form (POST + server validation)</h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Name</label><input name="name" required><label>Email</label><input type="email" name="email" required><label>Message</label><textarea name="message" required></textarea><button>Submit</button></form></section><?php if(file_exists(__DIR__.'/submissions.csv')){echo '<section class="panel"><h3>Stored records</h3><table><tr><th>Name</th><th>Email</th><th>Message</th><th>Time</th></tr>';if(($fp=fopen(__DIR__.'/submissions.csv','r'))){while(($r=fgetcsv($fp))!==false)echo '<tr><td>'.e($r[0]??'').'</td><td>'.e($r[1]??'').'</td><td>'.e($r[2]??'').'</td><td>'.e($r[3]??'').'</td></tr>';fclose($fp);}echo '</table></section>';}page_footer();?>